import React from 'react';
import './Posts.css';
import { useState } from 'react';
import Comments from './Comments';
import Share from './Share';
import CommentGen from './CommentGen';



function Posts({ id, userPic, name, text, photo, date, like, comments, commentsInfo,  onLike, onDelete }) {
    const [commentOpen, setCommentOpen] = useState(false);
    const [shareOpen, setShareOpen] = useState(false);
    const [liked, setLiked] = useState(false);
    const [commentsList,setCommentsList] = useState(commentsInfo);

    const onLikeClicked = () => {
        if (!liked) {
            onLike(1)
        }
        else { onLike(-1) } setLiked(!liked)
    }

    return (
        <div class="posts">
            <div class="Posts.html?id={id}">
                <div className="card">
                    <button type="button-close" class="btn-close" onClick={onDelete}  ></button>
                    <div className="post">
                        <div className='user'>
                            <div className='userInfo'>
                                <img src={userPic} class="card-img-bottom" alt="userPec"></img>
                                <div className='information'>
                                    <span className="name">{name}</span>
                                    <span className='date'>{date}</span>
                                </div>
                            </div>
                        </div>
                        <div className='body'>
                            <p class="card-text">{text}</p>
                            <img src={photo} class="card-img" alt=""></img>
                        </div>
                        <div class="postsInfo">
                            <div class="infleft">
                                <span>{like} likes</span>
                            </div>
                            <div class="infright">
                                <span>{comments} comments</span>
                            </div>
                        </div>
                        <div class="bottonPosts">
                            <div class="item">
                                <button type="button" class="btn btn-light" onClick={onLikeClicked}><i class="bi bi-suit-heart"></i> Likes</button>
                            </div>

                            <div class="item">
                                <button type="button" class="btn btn-light" onClick={() => setCommentOpen(!commentOpen)}><i class="bi bi-chat-dots"></i> Comments </button>
                            </div>
                            <div class="item">
                                <button type="button" class="btn btn-light" onClick={() => setShareOpen(!shareOpen)}><i class="bi bi-arrow-up-left-circle"></i> Share </button>
                            </div>
                        </div>
                        {shareOpen && <Share />}
                        {commentOpen && <CommentGen commentsList={commentsList} setCommentsList={setCommentsList}/> }
                        {commentOpen && commentsList.map ((comment)=>
                                    <Comments {...comment} />)}
                
                    </div>

                </div>
            </div>
        </div>
    );
}
export default Posts;
